code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 5]
    rs, cs = [r for r, c in cells], [c for r, c in cells]
    out = [[7 if grid[r][c] == 5 else grid[r][c] for c in range(w)] for r in range(h)]
    vertical_lines = [c for c in range(w) if all(grid[r][c] == 0 for r in range(h))]
    if len(vertical_lines) < 2:
        lo, hi, mid = min(rs), max(rs), (min(rs)+max(rs))//2
        for r in range(h):
            for c in range(w):
                if lo <= r <= hi:
                    out[r][c] = 5 if r == mid else (0 if r in (lo+1, hi-1) else 7)
                elif grid[r][c] == 0 and any(grid[x][c] == 7 for x in range(h)):
                    out[r][c] = 0
                else:
                    out[r][c] = 7
    else:
        lo, hi, mid = min(cs), max(cs), (min(cs)+max(cs))//2
        for r in range(h):
            for c in range(w):
                if lo <= c <= hi:
                    out[r][c] = 5 if c == mid else (0 if c in (lo+1, hi-1) else 7)
                elif grid[r][c] == 0 and any(grid[r][x] == 7 for x in range(w)):
                    out[r][c] = 0
                else:
                    out[r][c] = 7
    return out
'''
